  48	    pub fn feed(self: *Handler, alloc: Allocator, byte: u8) void {
  49	        switch (self.state) {
  50	            .inactive => unreachable,
  51	
  52	            // We're ignoring this APC command, likely because we don't
  53	            // recognize it so there is no need to store the data in memory.
  54	            .ignore => return,
  55	
  56	            // Unsupported APC content is retained only when enabled.
  57	            .unknown => |*unknown| unknown.append(&.{byte}),
  58	
  59	            // We identify the APC command by the first byte.
  60	            .identify => |*id| id: {
  61	                // Kitty graphics is detected immediately on the `G` byte,
  62	                // since commands begin immediately after with no termination
  63	                // character after the 'G'.
  64	                if (id.len == 0 and byte == 'G') {
  65	                    if (comptime build_options.kitty_graphics) {
  66	                        if (self.enabled.contains(.kitty)) {
  67	                            self.state = .{ .kitty = .init(
  68	                                alloc,
  69	                                self.max_bytes.get(.kitty) orelse
  70	                                    Protocol.defaultMaxBytes(.kitty),
  71	                            ) };
