 165	    /// Feed a slice of bytes to the handler. This is equivalent to
 166	    /// calling feed for each byte in order, but protocol payload bytes
 167	    /// are passed through in bulk so large payloads (e.g. Kitty graphics
 168	    /// images) avoid per-byte dispatch overhead.
 169	    pub fn feedSlice(self: *Handler, alloc: Allocator, bytes: []const u8) void {
 170	        var rem = bytes;
 171	        while (rem.len > 0) {
 172	            switch (self.state) {
 173	                .inactive => unreachable,
 174	
 175	                // We're ignoring this APC command; drop the whole slice.
 176	                .ignore => return,
 177	
 178	                // We're capturing an unknown APC command, so store it.
 179	                .unknown => |*unknown| {
 180	                    unknown.append(rem);
 181	                    return;
 182	                },
 183	
 184	                // Identification consumes at most a few bytes; step
 185	                // through them one at a time until the state changes.
 186	                .identify => {
 187	                    self.feed(alloc, rem[0]);
 188	                    rem = rem[1..];
 189	                },
 190	
 191	                .kitty => |*p| if (comptime build_options.kitty_graphics) {
 192	                    p.feedSlice(rem) catch |err| {
 193	                        log.warn("kitty graphics protocol error: {}", .{err});
 194	                        p.deinit();
 195	                        self.state = .ignore;
 196	                    };
 197	                    return;
 198	                } else unreachable,
 199	
 200	                .glyph => |*p| if (comptime build_options.glyph_protocol) {
 201	                    p.feedSlice(rem) catch |err| {
 202	                        log.warn("glyph protocol error: {}", .{err});
 203	                        p.deinit();
 204	                        self.state = .ignore;
 205	                    };
 206	                    return;
 207	                } else unreachable,
 208	            }
 209	        }
 210	    }
