 124	    fn tryPut(self: *Handler, byte: u8) !?Command {
 125	        switch (self.state) {
 126	            .inactive,
 127	            .ignore,
 128	            => {},
 129	
 130	            .tmux => |*tmux| if (comptime build_options.tmux_control_mode) {
 131	                return .{
 132	                    .tmux = (try tmux.put(byte)) orelse return null,
 133	                };
 134	            } else unreachable,
 135	
 136	            .xtgettcap => |*list| {
 137	                if (list.written().len >= self.max_bytes) {
 138	                    return error.OutOfMemory;
