  if node=='n43': lines[i]=l+' src/termio/Termio.zig:466-482:vi src/termio/stream_handler.zig:121-136:di'
  if node=='n45': lines[i]=l+' src/terminal/Terminal.zig:4664-4687:di'
  if node=='n46': lines[i]=l+' src/terminal/device_status.zig:32-56:di src/terminal/device_status.zig:90-100:di src/terminal/size_report.zig:42-93:di src/apprt/surface.zig:66-67:d src/apprt/surface.zig:186-207:vi src/App.zig:293-293:vi src/App.zig:531-542:vi src/App.zig:604-612:vi'
